contract Settlement {
  event Settled(bytes32 indexed id);
  function transferPair(address a, address b) external onlyCompliant {
    require(safeTransfer(a, 1), "fail");
    require(transferFrom(b, address(this), 1), "fail");
    emit Settled(bytes32(0));
  }
}
